const fs = require('fs');

function main() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    // Função rápida para pular whitespace e pegar tokens
    function nextToken() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        const start = pos;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            pos++;
        }
        return input.slice(start, pos);
    }

    const nToken = nextToken();
    if (!nToken) return;
    const n = parseInt(nToken, 10);

    let s = '';
    for (let i = 0; i < n; i++) {
        s += nextToken();
    }

    for (let L = 1; L <= n; L++) {
        // Se L < n e o primeiro dígito é '0', não pode ser um inteiro válido >= 1
        // Mas o problema garante que a entrada é válida, e s[0] != '0' se A >= 1.
        const aStr = s.slice(0, L);
        let cur = BigInt(aStr);
        let idx = 0;
        let match = true;

        while (idx < n) {
            const curStr = cur.toString();
            const len = curStr.length;
            if (idx + len > n) {
                match = false;
                break;
            }

            // Comparação direta com a substring de s
            if (s.startsWith(curStr, idx)) {
                idx += len;
                cur += 1n;
            } else {
                match = false;
                break;
            }
        }

        if (match && idx === n) {
            console.log(aStr);
            return;
        }
    }
}

main();
